                 max-width: 750px; margin: auto; padding: 35px; background: #fff; border: 1px solid #e2e8f0; border-radius: 16px; box-shadow: 0 8px 25px rgba(18, 59, 112, 0.08); } .form-heading { text-align: center; margin-bottom: 30px; } .form-heading h1 { color: #123b70; margin-bottom: 10px; font-size: 30px; } .form-heading p { color: #64748b; line-height: 1.6; } .tech-form .form-group { margin-bottom: 20px; } .tech-form label { display: block; margin-bottom: 8px; color: #334155; font-weight: 600; } .tech-form input, .tech-form select, .tech-form textarea { width: 100%; box-sizing: border-box; padding: 13px 14px; border: 1px solid #cbd5e1; border-radius: 8px; font-size: 15px; font-family: inherit; background: #fff; } .tech-form input:focus, .tech-form select:focus, .tech-form textarea:focus { outline: none; border-color: #1769d2; box-shadow: 0 0 0 3px rgba(23, 105, 210, 0.12); } .tech-form textarea { min-height: 100px; resize: vertical; } .form-row { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; } .file-note { display: block; margin-top: 7px; font-size: 13px; color: #64748b; } .profile-preview { display: none; width: 120px; height: 120px; margin-top: 15px; border-radius: 50%; object-fit: cover; border: 3px solid #dbeafe; } .work-preview { display: grid; grid-template-columns: repeat(auto-fit, minmax(110px, 1fr)); gap: 12px; margin-top: 15px; } .work-preview img { width: 100%; height: 110px; object-fit: cover; border-radius: 8px; border: 1px solid #e2e8f0; } .tech-submit { width: 100%; border: none; border-radius: 8px; padding: 15px; background: #1769d2; color: #fff; font-size: 16px; font-weight: 600; cursor: pointer; } .tech-submit:hover { background: #0f4fa8; } .form-message { display: none; margin-top: 20px; padding: 14px; border-radius: 8px; line-height: 1.5; } .form-message.error { display: block; background: #fee2e2; color: #991b1b; } .form-message.success { display: block; background: #dcfce7; color: #166534; } .form-links { text-align: center; margin-top: 25px; color: #64748b; } .form-links a { color: #1769d2; text-decoration: none; font-weight: 600; } @media (max-width: 600px) { .tech-register-section { padding: 30px 15px; } .tech-register-card { padding: 25px 18px; } .form-row { grid-template-columns: 1fr; gap: 0; } .form-heading h1 { font-size: 25px; } } 
                 </style> 
