                 <body> <!-- Navigation --> <header class="navbar"> <div class="container nav-container"> <a href="index.php" class="logo">TechConnect</a> <nav> <a href="index.php">Home</a> <a href="technicians.php">Find Technicians</a> <a href="login.php">Login</a> </nav> </div> </header> <!-- Technician Registration --> <main class="tech-register-section"> <div class="tech-register-card"> <div class="form-heading"> <h1>Technician Registration</h1> <p> Create your professional profile and connect with customers who need your skills. </p> </div> <form class="tech-form" id="technicianRegisterForm"> <h3>Personal Information</h3> <div class="form-row"> <div class="form-group"> <label for="full_name">Full Name *</label> <input type="text" id="full_name" name="full_name" placeholder="Enter your full name" autocomplete="name" required > </div> <div class="form-group"> <label for="email">Email Address *</label> <input type="email" id="email" name="email" placeholder="example@email.com" autocomplete="email" required > </div> </div> <div class="form-row"> <div class="form-group"> <label for="phone">Phone Number *</label> <input type="tel" id="phone" name="phone" placeholder="Enter phone number" autocomplete="tel" required > </div> <div class="form-group"> <label for="location">Town / Location *</label> <input type="text" id="location" name="location" placeholder="e.g. Limbe" required > </div> </div> <div class="form-group"> <label for="profile_picture">Profile Picture</label> <input type="file" id="profile_picture" name="profile_picture" accept="image/jpeg,image/png,image/webp" > <span class="file-note"> Choose a JPG, PNG or WebP image. Maximum 2 MB. </span> <img id="profilePreview" class="profile-preview" alt="Profile picture preview"> </div> <hr> <h3>Professional Information</h3> <div class="form-row"> <div class="form-group"> <label for="service">Main Skill / Service *</label> <select id="service" name="service" required> <option value="">Select your service</option> <option value="Electrician">Electrician</option> <option value="Plumber">Plumber</option> <option value="Carpenter">Carpenter</option> <option value="Mechanic">Mechanic</option> <option value="Welder">Welder</option> <option value="Painter">Painter</option> <option value="IT Technician">IT Technician</option> <option value="Phone Repair">Phone Repair</option> <option value="Other">Other</option> </select> </div> <div class="form-group"> <label for="experience">Years of Experience *</label> <select id="experience" name="experience" required> <option value="">Select experience</option> <option value="Less than 1 year">Less than 1 year</option> <option value="1-2 years">1–2 years</option> <option value="3-5 years">3–5 years</option> <option value="6-10 years">6–10 years</option> <option value="More than 10 years">More than 10 years</option> </select> </div> </div> <div class="form-group"> <label for="skills">Other Skills</label> <input type="text" id="skills" name="skills" placeholder="e.g. wiring, installation, maintenance" > </div> <div class="form-group"> <label for="bio">About You / Work Experience *</label> <textarea id="bio" name="bio" placeholder="Describe your experience and the services you offer" required ></textarea> </div> <div class="form-group"> <label for="work_photos">Photos of Previous Work</label> <input type="file" id="work_photos" name="work_photos[]" accept="image/jpeg,image/png,image/webp" multiple > <span class="file-note"> Select up to 5 images, each no larger than 2 MB. These will only be previewed in this demo. </span> <div id="workPreview" class="work-preview"></div> </div> <hr> <h3>Account Security</h3> <div class="form-row"> <div class="form-group"> <label for="password">Password *</label> <input type="password" id="password" name="password" minlength="8" autocomplete="new-password" placeholder="At least 8 characters" required > </div> <div class="form-group"> <label for="confirm_password">Confirm Password *</label> <input type="password" id="confirm_password" name="confirm_password" minlength="8" autocomplete="new-password" placeholder="Repeat password" required > </div> </div> <button type="submit" class="tech-submit"> Create Technician Account </button> <div id="formMessage" class="form-message" role="status" aria-live="polite"></div> </form> <div class="form-links"> Already registered? <a href="login.php">Log in</a> <br><br> <a href="register.php">← Back to account selection</a> </div> </div> </main> <!-- Footer --> <footer class="footer"> <div class="container"> <p> &copy; <?php echo date("Y"); ?> TechConnect. All rights reserved. </p> </div> </footer> <script> const technicianForm = document.getElementById("technicianRegisterForm"); const formMessage = document.getElementById("formMessage"); const profileInput = document.getElementById("profile_picture"); const profilePreview = document.getElementById("profilePreview"); const workInput = document.getElementById("work_photos"); const workPreview = document.getElementById("workPreview"); const MAX_SIZE = 2 * 1024 * 1024; const allowedTypes = [ "image/jpeg", "image/png", "image/webp" ]; function showMessage(message, type) { formMessage.textContent = message; formMessage.className = "form-message " + type; } function validImage(file) { return allowedTypes.includes(file.type) && file.size <= MAX_SIZE; } profileInput.addEventListener("change", function() { profilePreview.style.display = "none"; const file = this.files[0]; if (!file) return; if (!validImage(file)) { this.value = ""; showMessage( "Choose a JPG, PNG or WebP profile picture no larger than 2 MB.", "error" ); return; } profilePreview.src = URL.createObjectURL(file); profilePreview.style.display = "block"; formMessage.className = "form-message"; formMessage.textContent = ""; }); workInput.addEventListener("change", function() { workPreview.innerHTML = ""; const files = Array.from(this.files); if (files.length > 5) { this.value = ""; showMessage("Please select no more than 5 work photos.", "error"); return; } for (const file of files) { if (!validImage(file)) { this.value = ""; workPreview.innerHTML = ""; showMessage( "Each work photo must be JPG, PNG or WebP and no larger than 2 MB.", "error" ); return; } } files.forEach(function(file) { const image = document.createElement("img"); image.src = URL.createObjectURL(file); image.alt = "Previous work preview"; workPreview.appendChild(image); }); formMessage.className = "form-message"; formMessage.textContent = ""; }); technicianForm.addEventListener("submit", function(event) { event.preventDefault(); const password = document.getElementById("password").value; const confirmPassword = document.getElementById("confirm_password").value; if (password !== confirmPassword) { showMessage( "Your passwords do not match. Please try again.", "error" ); return; } showMessage( "Form validation successful! Account creation and photo uploads will work after the backend is connected.", "success" ); }); </script> </body> </html>